  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `event_category` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pertunjukan',
