INSERT INTO `events` VALUES (1,1,1,'Shine in Harmony','shine-in-harmony','boro-event-posters/01M227FP2787SGV2ADG9VBW03S.png','<p>Celebrating a cherished tradition and honoring the rich cultural tapestry of the Mid-Autumn Festival through music, dance, and verse.</p><p><strong>Penyelenggara:</strong> Nanyang Zhi Hui Modern Indonesian School</p><p><strong>Syarat &amp; Ketentuan:</strong></p><ul><li><p>Penonton wajib hadir 30 menit sebelum sesi pertunjukan dimulai.</p></li><li><p>E-tiket ber-QR code wajib ditunjukkan kepada petugas pintu masuk venue.</p></li><li><p>Dilarang membawa makanan dan minuman dari luar ke dalam Auditorium.</p></li></ul>','Pertunjukan',24,'registration',1,'2026-08-28 11:09:18','2026-09-09 05:18:48');
/*!40000 ALTER TABLE `events` ENABLE KEYS */;
UNLOCK TABLES;

